    /// Map a tree-sitter `node.kind()` string to a `RawKind`.
    ///
    /// LOUD on unknown: only NAMED kinds are passed here (the lowerer classifies
    /// named children); an unknown string means the binary was built against a
    /// different grammar than it is parsing — a bug, not data.
    pub fn from_raw(s: &str) -> RawKind {
        match Self::try_from_raw(s) {
            Some(k) => k,
            None => panic!(
                "al-syntax: unknown node kind {s:?} — grammar/binary mismatch \
                 (regenerate with `cargo run -p xtask -- gen-syntax`)"
            ),
        }
    }

